import { memo } from 'react';
import { Image, Text, View, StyleSheet } from 'react-native';
import type { FeedItem } from '../screens/ImageFeedScreen';

interface ImageRowProps {
  item: FeedItem;
}

export const ImageRow = memo(function ImageRow({ item }: ImageRowProps): JSX.Element {
  return (
    <View style={styles.row}>
      <Image
        style={styles.image}
        source={{ uri: item.thumbnailUrl }}
        resizeMode="cover"
        defaultSource={require('../assets/placeholder.png')}
      />
      <Text style={styles.caption}>{item.caption}</Text>
    </View>
  );
});

const styles = StyleSheet.create({
  row: { padding: 8, gap: 4 },
  image: { width: '100%', height: 200, borderRadius: 8 },
  caption: { fontSize: 14, color: '#333' },
});

import { useCallback, useEffect, useMemo, useState } from 'react';
import { FlatList, Text, View, ActivityIndicator, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { ImageRow } from '../components/ImageRow';

export interface FeedItem {
  id: string;
  thumbnailUrl: string;
  caption: string;
}

async function fetchFeed(): Promise<FeedItem[]> {
  const response = await fetch('https://api.example.com/feed');
  if (!response.ok) throw new Error(`Request failed: ${response.status}`);
  return (await response.json()) as FeedItem[];
}

export function ImageFeedScreen(): JSX.Element {
  const [items, setItems] = useState<FeedItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchFeed()
      .then(setItems)
      .catch(err => setError(err instanceof Error ? err.message : 'Failed'))
      .finally(() => setLoading(false));
  }, []);

  const getItemLayout = useMemo(
    () => (_, index: number) => ({ length: 216, offset: 216 * index, index }),
    []
  );

  if (loading) {
    return <View style={styles.center}><ActivityIndicator /></View>;
  }
  if (error !== null && items.length === 0) {
    return <View style={styles.center}><Text style={styles.error}>{error}</Text></View>;
  }
  return (
    <SafeAreaView style={styles.safe}>
      <FlatList
        data={items}
        keyExtractor={item => item.id}
        renderItem={({ item }) => <ImageRow item={item} />}
        getItemLayout={getItemLayout}
        initialNumToRender={8}
        maxToRenderPerBatch={10}
        ListEmptyComponent={<Text>No images yet.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  error: { color: '#FF3B30' },
});
